using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");

// Configure the chat client with tool support
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT") ?? "https://api.openai.com/v1";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException(
    "Set the OPENAI_API_KEY environment variable to your OpenAI (or compatible) API key.");
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

var openAiClient = new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey),
    new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) });

var notepad = new Notepad();

IChatClient client = openAiClient.GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]
};

// Determine research topic
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
Console.WriteLine($"Researching topic: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly.

        Follow these steps:
        1. Search the web for information about the topic (make multiple searches with different queries to get broad coverage).
        2. Take notes on the key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a comprehensive summary.

        Always use the tools available to you. Search at least 2-3 times with different queries before summarizing.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

// Run the agent loop
var response = await client.GetChatResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

Console.WriteLine("\n=== Collected Notes ===\n");
foreach (var note in notepad.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

/// <summary>Simulated web search tool that returns results for a query.</summary>
static class WebSearchTool
{
    [Description("Searches the web for the given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query string")] string query)
    {
        // In a real implementation, this would call a search API (e.g., Bing, Google, Tavily).
        // Here we simulate results to demonstrate the agent loop.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        var results = new[]
        {
            new { Title = $"Latest research on {query}", Snippet = $"Recent studies show significant progress in {query}. Researchers have developed new approaches that improve performance by up to 40%." },
            new { Title = $"{query} - Overview and Applications", Snippet = $"The field of {query} encompasses multiple sub-disciplines. Key applications include optimization, simulation, and machine learning integration." },
            new { Title = $"Future of {query}", Snippet = $"Experts predict that {query} will see major breakthroughs in the next 5 years, driven by increased funding and cross-disciplinary collaboration." },
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

/// <summary>Note-taking tool that stores research findings.</summary>
class Notepad
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Adds a note to the research notepad for later reference.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

